<script>
    // Adjust vertical line height dynamically according to testimonial text height
    function adjustLineHeight() {
        const content = document.getElementById("testimonial-content");
        const verticalLine = document.getElementById("vertical-line");
        if (content && verticalLine) {
            const height = content.offsetHeight;
            verticalLine.style.height = height + "px";
        }
    }
    window.addEventListener("load", adjustLineHeight);
    window.addEventListener("resize", adjustLineHeight);
</script>

